//
// Spy::watch<M>(): a watcher of a typed message (vehicle_sil::j1939::codec, generated by
// vehicle_sil_add_j1939_codec() or written by hand in the same form) that publishes each of its
// signals and when and how often it came, without code of one's own:
//
//     #include "cal_messages.hpp"            // generated: cal::Write and its signals
//     #include "vehicle_sil/spy/watch.hpp"
//     spy_.watch<cal::Write>("write", {.from = 0xF9, .to = 0x21});   // write.address, write.count ...
//
// A header of its own, so that code that does not use the codec does not include it (spy.hpp
// does not). Include it where Spy::watch() is called.
//
// NOT COMPARED WITH THE STANDARD. The Watch reads what its Spy's Listener hands on.
#pragma once

#include "vehicle_sil/control/agent.hpp"
#include "vehicle_sil/core/sim_time.hpp"
#include "vehicle_sil/j1939/codec.hpp"
#include "vehicle_sil/j1939/types.hpp"
#include "vehicle_sil/spy/spy.hpp"

#include <array>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>

namespace vehicle_sil::spy {

namespace detail {

/// The items a Watch publishes beside the signals ("<as>.count" ...; "state" for
/// "<as>.<signal>.state"): no signal may have one of these names.
inline constexpr std::array<std::string_view, 7> kWatchItems{"count", "last_ms", "period_ms", "size",
                                                             "invalid", "stale", "state"};

[[nodiscard]] constexpr bool is_watch_item(std::string_view name) noexcept
{
    for (const std::string_view item : kWatchItems)
    {
        if (item == name)
        {
            return true;
        }
    }
    return false;
}

/// true for an EnumSignal (its value() is an enumerator).
template <class S>
inline constexpr bool is_enum_signal = std::is_enum_v<typename decltype(std::declval<const S&>().value())::value_type>;

/// true: every valid raw value of S plus `offset` (a whole number of std::int64_t) is a
/// std::int64_t.
template <class S, std::int64_t offset>
[[nodiscard]] constexpr bool fits_int64() noexcept
{
    constexpr std::int64_t most = (std::numeric_limits<std::int64_t>::max)();
    constexpr std::int64_t least = (std::numeric_limits<std::int64_t>::min)();
    if constexpr (std::is_signed_v<typename S::raw_type>)
    {
        return offset >= 0 ? S::raw_max <= most - offset : S::raw_min >= least - offset;
    }
    else
    {
        // raw_min >= 0 and offset > -9.0e18: the sum stays above the least.
        return S::raw_max <= static_cast<std::uint64_t>(most) &&
               static_cast<std::int64_t>(S::raw_max) <= most - (offset > 0 ? offset : 0);
    }
}

/// true: the signal's value is published as an integer (an enumeration, or scale 1 with a whole
/// offset, where every valid value is a std::int64_t); otherwise as a real number (e.g. a 64-bit
/// counter whose valid values go above 2^63 - 1).
template <class S>
[[nodiscard]] constexpr bool is_integer_signal() noexcept
{
    if constexpr (is_enum_signal<S>)
    {
        return true;
    }
    else
    {
        constexpr double offset = S::layout.offset;
        if constexpr (S::layout.scale == 1.0 && offset > -9.0e18 && offset < 9.0e18 &&
                      offset == static_cast<double>(static_cast<std::int64_t>(offset)))
        {
            return fits_int64<S, static_cast<std::int64_t>(offset)>();
        }
        else
        {
            return false;
        }
    }
}

/// true: the signal can hold a raw value that is not Valid (a special value, a range narrower
/// than its bits, or an enumeration): it gets "<as>.<signal>.state".
template <class S>
[[nodiscard]] constexpr bool can_be_invalid() noexcept
{
    return !S::specials.empty() || is_enum_signal<S> || S::raw_min != S::lowest_raw() ||
           S::raw_max != S::highest_raw();
}

/// The values of "<as>.<signal>.state": codec::SignalState, and -1 before the first message.
inline constexpr int kStateNone = -1;
static_assert(static_cast<int>(j1939::codec::SignalState::Valid) == 0 &&
              static_cast<int>(j1939::codec::SignalState::OutOfRange) == 1 &&
              static_cast<int>(j1939::codec::SignalState::Error) == 2 &&
              static_cast<int>(j1939::codec::SignalState::NotAvailable) == 3 &&
              static_cast<int>(j1939::codec::SignalState::Special) == 4 &&
              static_cast<int>(j1939::codec::SignalState::Undefined) == 5);

inline std::vector<control::EnumItem> state_items()
{
    return {{"none", kStateNone}, {"valid", 0},   {"error", 2},    {"not_available", 3},
            {"special", 4},       {"out_of_range", 1}, {"undefined", 5}};
}

[[nodiscard]] inline std::int64_t whole_ms(SimDuration d) noexcept
{
    return std::chrono::duration_cast<std::chrono::milliseconds>(d).count();
}

} // namespace detail

/// The watcher of Spy::watch<M>(as, options): it hears the messages of M's PGN that come from
/// options.from and go to options.to (each if given) and decode as M (M::decode(): long enough,
/// and the selector of M if it has one), and publishes:
/// - "<as>.<signal>" for each signal of M: its latest valid value, with the signal's unit. An
///   integer for an enumeration (the raw value; no names yet) and for a signal of scale 1 with a
///   whole offset whose valid values all fit std::int64_t, a real number otherwise. 0 until a valid value came; a value that is not
///   valid leaves it as it was.
/// - "<as>.<signal>.state" for each signal that can hold a value that is not valid (special
///   values, a valid range narrower than its bits, an enumeration): an enumeration of none
///   (no message yet), valid, error, not_available, special, out_of_range, undefined
///   (j1939::codec::SignalState), as the latest message held it.
/// - "<as>.count": the messages heard. "<as>.invalid": those with a signal that was not valid.
/// - "<as>.last_ms": the time of the latest message, in whole ms (-1: none yet).
/// - "<as>.period_ms": the time between the latest message and the one before, in whole ms
///   (-1: fewer than two).
/// - "<as>.size": the bytes of the latest message (more than M::kLength if it came longer).
/// - "<as>.stale", with options.stale_after only: true while the latest message (before the
///   first one: the ECU's first step) is more than stale_after older than the ECU's step. It
///   changes in the steps of the ECU, so how soon it shows depends on the step size.
/// "Latest" is by Message::time: a message older than the latest one (a connection is handed on
/// after the receiver's acknowledgement, after frames that came later) is counted in count and
/// invalid and changes nothing else. Of two messages with the same time (one sender's step), the
/// one handed on later is the latest, and period_ms is 0.
///
/// No signal of M may be named like an item above (count, last_ms, period_ms, size, invalid,
/// stale, state): a build error says so; rename the signal in M's definition. If the ECU has one
/// of the variables already, the watch publishes none (std::invalid_argument). Allocates when it
/// is made only.
template <class M>
class Watch final
{
    static_assert(j1939::codec::MessageType<M>,
                  "vehicle_sil::spy::Watch<M>: M is no message type of vehicle_sil::j1939::codec (see MessageType in "
                  "vehicle_sil/j1939/codec.hpp): generate it with vehicle_sil_add_j1939_codec() or write it in that form");

public:
    Watch(Scope& scope, WatchOptions options) : scope_(scope), options_(options)
    {
        if (options_.stale_after && *options_.stale_after <= SimDuration::zero())
        {
            throw std::invalid_argument("vehicle_sil::spy::Spy::watch() \"" + scope.name() +
                                        "\": WatchOptions::stale_after is " +
                                        std::to_string(options_.stale_after->count()) +
                                        " ns: give a time above 0, or leave it out for no \"" + scope.name() +
                                        ".stale\"");
        }
        M probe{};
        require_free(scope);
        std::size_t count = 0;
        std::as_const(probe).for_each_signal([&count](const auto&) { ++count; });
        signals_.resize(count);
        std::size_t index = 0;
        std::as_const(probe).for_each_signal([this, &index](const auto& signal) {
            publish_signal<std::remove_cvref_t<decltype(signal)>>(index++);
        });
        scope.output("count", &count_, {.description = "Messages heard"});
        scope.output("last_ms", [this] { return latest_ ? detail::whole_ms(latest_time_.time_since_epoch()) : -1; },
                     {.unit = "ms", .description = "Time of the latest message (-1: none yet)"});
        scope.output("period_ms", [this] { return period_ ? detail::whole_ms(*period_) : -1; },
                     {.unit = "ms", .description = "Time between the latest message and the one before (-1: fewer than two)"});
        scope.output("size", &size_, {.unit = "bytes", .description = "Bytes of the latest message"});
        scope.output("invalid", &invalid_, {.description = "Messages with a signal that was not valid"});
        if (options_.stale_after)
        {
            scope.on_step([this](SimTime now) {
                if (!first_step_)
                {
                    first_step_ = now;
                }
            });
            scope.output("stale", [this] { return stale(); },
                         {.description = "true: no message for more than " +
                                         std::to_string(detail::whole_ms(*options_.stale_after)) + " ms"});
        }
        scope.on_message(M::kPgn, [this](const j1939::Message& message) { hear(message); });
    }
    Watch(const Watch&) = delete;
    Watch& operator=(const Watch&) = delete;
    Watch(Watch&&) = delete;
    Watch& operator=(Watch&&) = delete;
    ~Watch() = default;

    /// The messages heard ("<as>.count").
    [[nodiscard]] std::int64_t count() const noexcept { return count_; }
    /// The latest message by time, whatever its signals held; empty before the first.
    [[nodiscard]] const std::optional<M>& latest() const noexcept { return latest_; }

private:
    /// All or nothing: std::invalid_argument before the first variable if the ECU has one of
    /// the watch's variables already.
    void require_free(const Scope& scope) const
    {
        const auto require = [&scope](const std::string& item) {
            if (scope.has_variable(item))
            {
                throw std::invalid_argument("vehicle_sil::spy::Spy::watch() \"" + scope.name() + "\": the ECU has the variable \"" +
                                            scope.name() + "." + item +
                                            "\" already, and the watch publishes it too: give the watch another name, or "
                                            "rename the other variable (the watch published nothing)");
            }
        };
        M probe{};
        std::as_const(probe).for_each_signal([&require](const auto& signal) {
            using S = std::remove_cvref_t<decltype(signal)>;
            require(std::string(S::name));
            if constexpr (detail::can_be_invalid<S>())
            {
                require(std::string(S::name) + ".state");
            }
        });
        for (const char* item : {"count", "last_ms", "period_ms", "size", "invalid"})
        {
            require(item);
        }
        if (options_.stale_after)
        {
            require("stale");
        }
    }

    struct SignalValue
    {
        std::int64_t integer = 0;
        double real = 0.0;
        int state = detail::kStateNone;
    };

    template <class S>
    void publish_signal(std::size_t index)
    {
        static_assert(!detail::is_watch_item(S::name),
                      "vehicle_sil::spy::Spy::watch<M>(): a signal of M is named like an item the watch publishes "
                      "(count, last_ms, period_ms, size, invalid, stale, state), so two variables would have one name: "
                      "rename the signal in M's definition (the YAML file, or the type written by hand)");
        const std::string name(S::name);
        std::string description = "Latest valid value of the signal";
        if constexpr (S::spn.has_value())
        {
            description += " (SPN " + std::to_string(*S::spn) + ")";
        }
        if constexpr (detail::can_be_invalid<S>())
        {
            description += "; " + name + ".state says what the latest message held";
        }
        if constexpr (detail::is_integer_signal<S>())
        {
            scope_.output(name, [this, index] { return signals_[index].integer; },
                          {.unit = std::string(S::unit), .description = description});
        }
        else
        {
            scope_.output(name, [this, index] { return signals_[index].real; },
                          {.unit = std::string(S::unit), .description = description});
        }
        if constexpr (detail::can_be_invalid<S>())
        {
            scope_.output_enum(name + ".state", [this, index] { return signals_[index].state; }, detail::state_items(),
                               {.description = "What the signal held in the latest message (none: no message yet)"});
        }
    }

    template <class S>
    static void take(SignalValue& out, const S& signal) noexcept
    {
        out.state = static_cast<int>(signal.state());
        if (!signal.valid())
        {
            return;
        }
        if constexpr (detail::is_enum_signal<S>)
        {
            out.integer = static_cast<std::int64_t>(signal.bits());
        }
        else if constexpr (detail::is_integer_signal<S>())
        {
            out.integer = static_cast<std::int64_t>(signal.raw()) + static_cast<std::int64_t>(S::layout.offset);
        }
        else
        {
            out.real = signal.value_or(0.0);
        }
    }

    void hear(const j1939::Message& message)
    {
        if ((options_.from && message.source != *options_.from) || (options_.to && message.destination != *options_.to))
        {
            return;
        }
        const std::optional<M> decoded = M::decode(message.data);
        if (!decoded)
        {
            return;
        }
        ++count_;
        bool valid = true;
        decoded->for_each_signal([&valid](const auto& signal) { valid = valid && signal.valid(); });
        if (!valid)
        {
            ++invalid_;
        }
        if (latest_ && message.time < latest_time_)
        {
            return; // older than the latest: counted only
        }
        if (latest_)
        {
            period_ = message.time - latest_time_;
        }
        latest_time_ = message.time;
        size_ = static_cast<std::int64_t>(message.data.size());
        std::size_t index = 0;
        decoded->for_each_signal([this, &index](const auto& signal) { take(signals_[index++], signal); });
        latest_ = decoded;
    }

    [[nodiscard]] bool stale() const noexcept
    {
        if (!latest_ && !first_step_)
        {
            return false; // before the first step
        }
        const SimTime since = latest_ ? latest_time_ : *first_step_;
        return scope_.now() - since > *options_.stale_after;
    }

    Scope& scope_;
    WatchOptions options_;
    std::vector<SignalValue> signals_;
    std::optional<M> latest_{};
    SimTime latest_time_{};
    std::optional<SimDuration> period_{};
    std::optional<SimTime> first_step_{}; ///< "<as>.stale" before the first message counts from it
    std::int64_t count_ = 0;
    std::int64_t invalid_ = 0;
    std::int64_t size_ = 0;
};

} // namespace vehicle_sil::spy
